dules/motion-dom/src/projection/geometry/utils.ts","../node_modules/motion-dom/src/projection/shared/stack.ts","../node_modules/motion-dom/src/projection/utils/compare-by-depth.ts","../node_modules/motion-dom/src/projection/utils/flat-tree.ts","../node_modules/motion-dom/src/projection/node/create-projection-node.ts","../node_modules/motion-dom/src/utils/is-svg-svg-element.ts","../node_modules/motion-dom/src/animation/animate/single-value.ts","../node_modules/motion-dom/src/projection/styles/transform.ts","../node_modules/motion-dom/src/projection/node/DocumentProjectionNode.ts","../node_modules/motion-dom/src/projection/node/HTMLProjectionNode.ts","../node_modules/framer-motion/src/motion/features/drag.ts","../node_modules/framer-motion/src/gestures/drag/index.ts","../node_modules/motion-dom/src/gestures/utils/setup.ts","../node_modules/motion-dom/src/gestures/hover.ts","../node_modules/framer-motion/src/gestures/hover.ts","../node_modules/motion-dom/src/utils/is-html-element.ts","../node_modules/motion-dom/src/gestures/utils/is-node-or-child.ts","../node_modules/motion-dom/src/gestures/press/utils/state.ts","../node_modules/motion-dom/src/gestures/press/utils/keyboard.ts","../node_modules/motion-dom/src/gestures/press/index.ts","../node_modules/framer-motion/src/gestures/press.ts","../node_modules/framer-motion/src/motion/features/viewport/observers.ts","../node_modules/framer-motion/src/motion/features/viewport/index.ts","../node_modules/framer-motion/src/motion/features/gestures.ts","../node_modules/framer-motion/src/gestures/focus.ts","../node_modules/framer-motion/src/motion/features/layout.ts","../node_modules/framer-motion/src/render/components/motion/proxy.ts","../node_modules/framer-motion/src/render/components/motion/feature-bundle.ts","lib/AuthContext.jsx","components/ProtectedRoute.jsx","components/icons.jsx","components/AppShell.jsx","components/Navbar.jsx","pages/Home.jsx","pages/Login.jsx","pages/Apps.jsx","../node_modules/framer-motion/src/utils/use-composed-ref.ts","../node_modules/framer-motion/src/components/AnimatePresence/PopChild.tsx","../node_modules/framer-motion/src/components/AnimatePresence/PresenceChild.tsx","../node_modules/framer-motion/src/components/AnimatePresence/utils.ts","../node_modules/framer-motion/src/components/AnimatePresence/index.tsx","lib/search.js","lib/db.live.js","demo/db.demo.js","lib/db.js","apps/pricing/styles.js","apps/pricing/Toast.jsx","apps/pricing/BrandSelect.jsx","lib/xlsxExport.js","apps/pricing/SingleSKU.jsx","apps/pricing/BulkUpdatePaste.jsx","apps/pricing/MassOverride.jsx","apps/pricing/BulkUpload.jsx","lib/csvExport.js","apps/pricing/ItemList.jsx","apps/pricing/Brands.jsx","apps/pricing/Rollback.jsx","apps/pricing/ProjectBulkEdit.jsx","apps/pricing/ProjectItems.jsx","apps/PricingMaster.jsx","demo/demoErp.js","apps/others/ERPAutomation.jsx","apps/others/CostLookup.jsx","apps/others/GlobalMarkupExport.jsx","apps/OthersMaster.jsx","App.js","index.js"],"sourcesContent":["// ─────────────────────────────────────────────────────────────\n// DEMO MODE FLAG\n// When REACT_APP_DEMO === 'true' the whole app runs against an\n// in-memory fake dataset (see demoData.js / db.demo.js) with a\n// mock auth session — no Supabase, no ERP, no real credentials.\n// Build with:  npm run build:demo   ·   Dev:  npm run start:demo\n// ─────────────────────────────────────────────────────────────\nexport const DEMO = process.env.REACT_APP_DEMO === 'true';\n\n// The signed-in identity used throughout the demo.\nexport const DEMO_USER = { id: 'demo-user', email: 'demo@castillo.lab' };\n","// ─────────────────────────────────────────────────────────────\r\n// DEMO DATASET\r\n// A fully synthetic, self-contained pricing catalogue used when\r\n// the app runs in demo mode. No real brands, SKUs, costs or people.\r\n// Prices are computed with the real pricing engine (pricing.js) so\r\n// every margin, fill-rate and markup preview in the UI is coherent.\r\n//\r\n// The exported `store` is mutable — edits, imports, markup commits\r\n// and rollbacks mutate it in place so the demo behaves like a real\r\n// backend for the length of a session. A page reload reseeds.\r\n// ─────────────────────────────────────────────────────────────\r\nimport { calcMSRPs, calcCostBasedMSRPs, calcProjectPrice } from '../lib/pricing';\r\n\r\n// ── Exchange rates (to AED) ───────────────────────────────────\r\nexport const RATES = {\r\n  EUR: 3.95,\r\n  USD: 3.67,\r\n  GBP: 4.65,\r\n  AUD: 2.42,\r\n  JPY: 0.025,\r\n  SAR: 0.98,\r\n  QAR: 1.01,\r\n};\r\n\r\n// ── Fake team (updated_by / changed_by) ───────────────────────\r\nconst TEAM = [\r\n  'demo@castillo.lab',\r\n  'ava.pricing@castillo.lab',\r\n  'liam.ops@castillo.lab',\r\n  'noor.catalog@castillo.lab',\r\n];\r\n\r\n// ── Brands ────────────────────────────────────────────────────\r\n// markup_percentage = brand base markup, additional_markup_pct = optional 2nd pass\r\nconst BRAND_DEFS = [\r\n  { brand_code: 'KLIM',  brand_name: 'KLIM Motorsports',      markup: 12, additional: null, count: 8 },\r\n  { brand_code: 'ALPS',  brand_name: 'Alpine Star Gear',      markup: 10, additional: null, count: 9 },\r\n  { brand_code: 'SHOEI', brand_name: 'Shoei Helmets',         markup: 15, additional: null, count: 7 },\r\n  { brand_code: 'REVIT', brand_name: \"Revit Apparel\",         markup: 10, additional: 5,    count: 8 },\r\n  { brand_code: 'SIDI',  brand_name: 'Sidi Riding Boots',     markup: 18, additional: null, count: 6 },\r\n  { brand_code: 'GIVI',  brand_name: 'Givi Luggage Systems',  markup: 10, additional: null, count: 7 },\r\n  { brand_code: 'OXFD',  brand_name: 'Oxford Products',       markup: 8,  additional: null, count: 9 },\r\n  { brand_code: 'SENA',  brand_name: 'Sena Communications',   markup: 14, additional: 3,    count: 6 },\r\n];\r\n\r\nconst CURRENCIES = ['EUR', 'USD', 'GBP', 'AUD', 'JPY'];\r\nconst SOURCES    = ['Portal', 'File', 'Website', 'Invoice', 'Estimate'];\r\n\r\n// Product-name fragments to make item names read plausibly.\r\nconst NAME_HEAD = ['Adventure', 'Touring', 'Sport', 'Track', 'Urban', 'Enduro', 'Classic', 'Pro', 'Carbon', 'Alpine'];\r\nconst NAME_TAIL = ['Jacket', 'Glove', 'Helmet', 'Boot', 'Pant', 'Base Layer', 'Top Case', 'Tank Bag', 'Headset', 'Vest'];\r\nconst SIZES      = ['XS', 'S', 'M', 'L', 'XL', 'XXL', ''];\r\n\r\n// Deterministic pseudo-random so a reload always reseeds the same catalogue.\r\nfunction makeRng(seed) {\r\n  let s = seed >>> 0;\r\n  return () => {\r\n    s = (s * 1664525 + 1013904223) >>> 0;\r\n    return s / 0xffffffff;\r\n  };\r\n}\r\n\r\nconst pf2 = (v) => (v != null ? parseFloat(Number(v).toFixed(2)) : null);\r\nconst pick = (rng, arr) => arr[Math.floor(rng() * arr.length)];\r\n\r\nfunction daysAgo(n) {\r\n  const d = new Date();\r\n  d.setDate(d.getDate() - n);\r\n  d.setHours(9 + (n % 8), (n * 7) % 60, 0, 0);\r\n  return d.toISOString();\r\n}\r\n\r\n// ── Build one brand's items ───────────────────────────────────\r\nfunction buildBrandItems(def, rng) {\r\n  const items = [];\r\n  for (let i = 0; i < def.count; i++) {\r\n    const seq = 1000 + i;\r\n    const item_code = `${def.brand_code}-${seq}`;\r\n    const size = pick(rng, SIZES);\r\n    const item_name = `${def.brand_name.split(' ')[0]} ${pick(rng, NAME_HEAD)} ${pick(rng, NAME_TAIL)}${size ? ' ' + size : ''}`;\r\n    const barcode = String(628000000000 + def.brand_code.length * 1e6 + seq * 137 + i).slice(0, 13);\r\n\r\n    const cost_currency = pick(rng, CURRENCIES);\r\n    // EXW cost scaled per currency so JPY items aren't tiny.\r\n    const base = cost_currency === 'JPY' ? 4000 + Math.floor(rng() * 26000)\r\n               : 18 + Math.floor(rng() * 240);\r\n    const exw_cost = pf2(base);\r\n    const shipping_rate = pick(rng, [0, 3, 5, 7.5]);\r\n    const customs_duty_rate = pick(rng, [5, 5.5]);\r\n\r\n    // Roughly 1 in 6 items is priced from cost + target margin.\r\n    const costBased = rng() < 0.16;\r\n\r\n    const updated_at = daysAgo(2 + Math.floor(rng() * 220));\r\n    const updated_by = pick(rng, TEAM);\r\n\r\n    let row = {\r\n      item_code,\r\n      item_name,\r\n      brand_code: def.brand_code,\r\n      barcode,\r\n      cost_currency,\r\n      exw_cost,\r\n      shipping_rate,\r\n      customs_duty_rate,\r\n      msrp_primary_ex_vat: null,\r\n      msrp_primary_inc_vat: null,\r\n      msrp_primary_currency: null,\r\n      msrp_secondary_ex_vat: null,\r\n      msrp_secondary_inc_vat: null,\r\n      msrp_secondary_currency: null,\r\n      price_used: null,\r\n      target_margin_pct: null,\r\n      price_source: pick(rng, SOURCES),\r\n      cost_source: pick(rng, SOURCES),\r\n      msrp_aed: null, msrp_sar: null, msrp_qat: null,\r\n      real_msrp_aed: null, real_msrp_sar: null, real_msrp_qat: null,\r\n      uae_overridden: false, ksa_overridden: false, qat_overridden: false,\r\n      created_at: updated_at,\r\n      updated_at,\r\n      updated_by,\r\n    };\r\n\r\n    if (costBased) {\r\n      const target_margin_pct = pick(rng, [22, 25, 28, 30]);\r\n      const msrps = calcCostBasedMSRPs(exw_cost, cost_currency, target_margin_pct, RATES);\r\n      row = {\r\n        ...row,\r\n        price_used: 'cost_based',\r\n        target_margin_pct,\r\n        ...(msrps || {}),\r\n      };\r\n    } else {\r\n      // Vendor MSRP in the cost currency — comfortably above cost.\r\n      const msrp_primary_currency = cost_currency;\r\n      const msrp_primary_ex_vat = pf2(exw_cost * (1.9 + rng() * 0.9));\r\n      const msrp_primary_inc_vat = pf2(msrp_primary_ex_vat * 1.2);\r\n      const hasSecondary = rng() < 0.35;\r\n      const msrps = calcMSRPs(msrp_primary_ex_vat, msrp_primary_currency, def.markup, def.additional, RATES);\r\n      row = {\r\n        ...row,\r\n        msrp_primary_currency,\r\n        msrp_primary_ex_vat,\r\n        msrp_primary_inc_vat,\r\n        msrp_secondary_currency: hasSecondary ? msrp_primary_currency : null,\r\n        msrp_secondary_ex_vat: hasSecondary ? pf2(msrp_primary_ex_vat * 1.08) : null,\r\n        msrp_secondary_inc_vat: hasSecondary ? pf2(msrp_primary_ex_vat * 1.08 * 1.2) : null,\r\n        price_used: 'primary_ex_vat',\r\n        ...(msrps || {}),\r\n      };\r\n    }\r\n\r\n    // A few manual overrides to exercise the override-aware code paths.\r\n    if (rng() < 0.08 && row.msrp_aed) {\r\n      row.uae_overridden = true;\r\n      row.msrp_aed = pf2(row.msrp_aed * 1.03);\r\n    }\r\n\r\n    items.push(row);\r\n  }\r\n  return items;\r\n}\r\n\r\n// ── Assemble the full seed ────────────────────────────────────\r\nfunction seed() {\r\n  const brands = [];\r\n  const brandRules = [];\r\n  const pricingMaster = [];\r\n\r\n  BRAND_DEFS.forEach((def, bi) => {\r\n    brands.push({ brand_code: def.brand_code, brand_name: def.brand_name });\r\n    brandRules.push({\r\n      brand_code: def.brand_code,\r\n      markup_percentage: def.markup,\r\n      additional_markup_pct: def.additional,\r\n    });\r\n    const rng = makeRng(0x9e37 + bi * 7919);\r\n    pricingMaster.push(...buildBrandItems(def, rng));\r\n  });\r\n\r\n  // ── Project items (cost-driven quotation pricing) ──\r\n  const projRng = makeRng(0x51ed);\r\n  const PROJ = [\r\n    ['PRJ-ATLAS-01', 'Atlas Fleet Comms Kit',      'USD', 145],\r\n    ['PRJ-ATLAS-02', 'Atlas Rider Safety Bundle',  'EUR', 260],\r\n    ['PRJ-NOVA-01',  'Nova Track Day Package',      'EUR', 410],\r\n    ['PRJ-NOVA-02',  'Nova Pit Crew Apparel Set',   'GBP', 88],\r\n    ['PRJ-ORBIT-01', 'Orbit Adventure Luggage Set', 'EUR', 320],\r\n    ['PRJ-ORBIT-02', 'Orbit Winter Layering Kit',   'USD', 175],\r\n  ];\r\n  const projectItems = PROJ.map(([item_code, project_item_name, cost_currency, cost]) => {\r\n    const shipping_rate = pick(projRng, [0, 5, 7.5]);\r\n    const customs_duty_rate = pick(projRng, [5, 5.5]);\r\n    const target_margin_pct = pick(projRng, [20, 25, 25, 30, 35]);\r\n    const priced = calcProjectPrice({ cost, cost_currency, shipping_rate, customs_duty_rate, target_margin_pct }, RATES) || {};\r\n    const when = daysAgo(3 + Math.floor(projRng() * 90));\r\n    const who = pick(projRng, TEAM);\r\n    return {\r\n      item_code,\r\n      project_item_name,\r\n      cost,\r\n      cost_currency,\r\n      shipping_rate,\r\n      customs_duty_rate,\r\n      target_margin_pct,\r\n      msrp_aed_inc_vat: priced.msrp_aed_inc_vat ?? null,\r\n      msrp_aed_ex_vat: priced.msrp_aed_ex_vat ?? null,\r\n      msrp_sar: priced.msrp_sar ?? null,\r\n      msrp_qat: priced.msrp_qat ?? null,\r\n      uae_overridden: false, ksa_overridden: false, qat_overridden: false,\r\n      created_by: who,\r\n      updated_at: when,\r\n      updated_by: who,\r\n    };\r\n  });\r\n\r\n  // ── Price-history batches + detail rows ──\r\n  const batches = [];\r\n  const priceHistory = [];\r\n  let hid = 1;\r\n\r\n  const pushBatch = ({ operation_type, description, applied_by, daysBack, sampleBrand, factor, metadata }) => {\r\n    const batch_id = `demo-batch-${batches.length + 1}`;\r\n    const applied_at = daysAgo(daysBack);\r\n    const sample = pricingMaster.filter(it => !sampleBrand || it.brand_code === sampleBrand);\r\n    const rows = sample.slice(0, 24).map(it => {\r\n      const oldAed = it.msrp_aed;\r\n      const oldSar = it.msrp_sar;\r\n      const oldQat = it.msrp_qat;\r\n      return {\r\n        id: hid++,\r\n        batch_id,\r\n        item_code: it.item_code,\r\n        brand_code: it.brand_code,\r\n        operation_type,\r\n        changed_at: applied_at,\r\n        changed_by: applied_by,\r\n        old_msrp_aed: oldAed != null ? pf2(oldAed / factor) : null,\r\n        new_msrp_aed: oldAed,\r\n        old_msrp_sar: oldSar != null ? pf2(oldSar / factor) : null,\r\n        new_msrp_sar: oldSar,\r\n        old_msrp_qat: oldQat != null ? pf2(oldQat / factor) : null,\r\n        new_msrp_qat: oldQat,\r\n        old_exw_cost: it.exw_cost != null ? pf2(it.exw_cost / factor) : null,\r\n        new_exw_cost: it.exw_cost,\r\n        old_shipping_rate: it.shipping_rate,\r\n        new_shipping_rate: it.shipping_rate,\r\n        old_customs_duty_rate: it.customs_duty_rate,\r\n        new_customs_duty_rate: it.customs_duty_rate,\r\n      };\r\n    });\r\n    priceHistory.push(...rows);\r\n    batches.push({\r\n      batch_id,\r\n      operation_type,\r\n      description,\r\n      applied_at,\r\n      applied_by,\r\n      item_count: rows.length,\r\n      brand_count: sampleBrand ? 1 : new Set(rows.map(r => r.brand_code)).size,\r\n      metadata: metadata ?? null,\r\n    });\r\n  };\r\n\r\n  pushBatch({ operation_type: 'global_markup', description: 'Global markup — 8 brands, 60 items', applied_by: 'ava.pricing@castillo.lab', daysBack: 5,  factor: 1.05, metadata: { addMap: { REVIT: '5', SENA: '3' } } });\r\n  pushBatch({ operation_type: 'global_markup', description: 'Global markup — Q2 refresh, 4 brands', applied_by: 'demo@castillo.lab',       daysBack: 34, factor: 1.03 });\r\n  pushBatch({ operation_type: 'bulk_import',   description: 'Bulk import — SHOEI SS26 catalogue',   applied_by: 'noor.catalog@castillo.lab', daysBack: 12, sampleBrand: 'SHOEI', factor: 1.0 });\r\n  pushBatch({ operation_type: 'single_edit',   description: 'Single edit — KLIM cost correction',   applied_by: 'liam.ops@castillo.lab',    daysBack: 2,  sampleBrand: 'KLIM',  factor: 1.08 });\r\n\r\n  return {\r\n    rates: { ...RATES },\r\n    brands,\r\n    brandRules,\r\n    pricingMaster,\r\n    projectItems,\r\n    batches,\r\n    priceHistory,\r\n  };\r\n}\r\n\r\n// The single mutable in-memory store for the session.\r\nexport const store = seed();\r\n","// ─────────────────────────────────────────────────────────────\r\n// PRICING CALCULATIONS\r\n// One place to audit all math. No DB calls here — pure functions.\r\n// ─────────────────────────────────────────────────────────────\r\n\r\n// Compound two markups multiplicatively: base% + additional% applied on top\r\n// e.g. compoundMarkup(10, 5) = ((1.10 × 1.05) - 1) × 100 = 15.5%\r\nexport function compoundMarkup(base, additional) {\r\n  if (!additional) return base;\r\n  return ((1 + base / 100) * (1 + additional / 100) - 1) * 100;\r\n}\r\n\r\n// ── LANDED COST ───────────────────────────────────────────────\r\n\r\n/**\r\n * Fully landed cost in AED\r\n * exw_cost (vendor currency) × (1 + shipping_rate%) × FX rate × (1 + customs_duty_rate%)\r\n */\r\nexport function calcLandedCost({ exw_cost, shipping_rate, customs_duty_rate, cost_currency }, rates) {\r\n  if (exw_cost == null || exw_cost === '' || !cost_currency || !rates?.[cost_currency]) return null;\r\n  const afterShipping = exw_cost * (1 + (shipping_rate || 0) / 100);\r\n  const inAED = afterShipping * rates[cost_currency];\r\n  return inAED * (1 + (customs_duty_rate ?? 5.5) / 100);\r\n}\r\n\r\n// ── PRICE USED RESOLVER ───────────────────────────────────────\r\n\r\n/**\r\n * Resolve the selected MSRP value and its currency from an item\r\n */\r\nexport function resolvePriceUsed(item) {\r\n  const map = {\r\n    primary_ex_vat:    { value: item.msrp_primary_ex_vat,    currency: item.msrp_primary_currency },\r\n    primary_inc_vat:   { value: item.msrp_primary_inc_vat,   currency: item.msrp_primary_currency },\r\n    secondary_ex_vat:  { value: item.msrp_secondary_ex_vat,  currency: item.msrp_secondary_currency },\r\n    secondary_inc_vat: { value: item.msrp_secondary_inc_vat, currency: item.msrp_secondary_currency },\r\n  };\r\n  return map[item.price_used] || { value: null, currency: null };\r\n}\r\n\r\n// ── EXW MARGIN ────────────────────────────────────────────────\r\n\r\n/**\r\n * EXW margin — raw vendor price vs raw cost, both converted to AED\r\n * No markup, no shipping, no customs applied\r\n *\r\n * price_used_aed = price_used_value × price_currency_rate\r\n * cost_aed       = exw_cost × cost_currency_rate\r\n * exw_margin     = (price_used_aed - cost_aed) / price_used_aed × 100\r\n */\r\nexport function calcEXWMargin(item, rates) {\r\n  if (item.exw_cost == null || !item.cost_currency || !rates?.[item.cost_currency]) return null;\r\n  const { value, currency } = resolvePriceUsed(item);\r\n  if (value == null || !currency || !rates?.[currency]) return null;\r\n  const priceAED = value * rates[currency];\r\n  const costAED  = item.exw_cost * rates[item.cost_currency];\r\n  if (!priceAED || priceAED <= 0) return null;\r\n  return ((priceAED - costAED) / priceAED) * 100;\r\n}\r\n\r\n// ── MARGIN ────────────────────────────────────────────────────\r\n\r\n/**\r\n * Generic margin % — both values must be in AED\r\n * (selling_price_aed - cost_aed) / selling_price_aed × 100\r\n */\r\nexport function calcMargin(sellingPriceAED, costAED) {\r\n  if (sellingPriceAED == null || costAED == null || sellingPriceAED <= 0) return null;\r\n  return ((sellingPriceAED - costAED) / sellingPriceAED) * 100;\r\n}\r\n\r\n/**\r\n * Calculate all three country retail margins + EXW margin\r\n *\r\n * UAE margin  = (msrp_aed - landed_cost_aed) / msrp_aed × 100\r\n * KSA margin  = (msrp_sar × sar_rate - landed_cost_aed) / (msrp_sar × sar_rate) × 100\r\n * QAT margin  = (msrp_qat × qar_rate - landed_cost_aed) / (msrp_qat × qar_rate) × 100\r\n * EXW margin  = (price_used_aed - exw_cost_aed) / price_used_aed × 100\r\n */\r\nexport function calcAllMargins(item, rates) {\r\n  const landed = calcLandedCost(item, rates);\r\n  if (landed === null) return null;\r\n\r\n  const ksaAED = item.msrp_sar ? item.msrp_sar * (rates['SAR'] || 0.98) : null;\r\n  const qatAED = item.msrp_qat ? item.msrp_qat * (rates['QAR'] || 1.01) : null;\r\n\r\n  return {\r\n    landed_cost_aed: landed,\r\n    uae_margin:      calcMargin(item.msrp_aed, landed),\r\n    ksa_margin:      calcMargin(ksaAED, landed),\r\n    qat_margin:      calcMargin(qatAED, landed),\r\n    exw_margin:      calcEXWMargin(item, rates),\r\n  };\r\n}\r\n\r\n// ── MOD REMOVAL ───────────────────────────────────────────────\r\n\r\nexport function removeMOD(ceiled) {\r\n  const modMark = ceiled < 100 ? 0 : ceiled < 1000 ? 5 : ceiled < 5000 ? 10 : 20;\r\n  const modDiv  = ceiled < 100 ? 1 : 100;\r\n  const mod     = ceiled % modDiv;\r\n  const removed = ceiled - (mod > modMark ? 0 : mod);\r\n  return String(removed).slice(-2) === '00' ? removed - 0.05 : removed;\r\n}\r\n\r\n// ── SUGGESTED PRICES ─────────────────────────────────────────\r\n\r\nexport function suggestUAEPrice(priceUsedValue, priceCurrency, markupPercentage, rates) {\r\n  if (priceUsedValue == null || !priceCurrency || !rates?.[priceCurrency]) return null;\r\n  const inAED    = priceUsedValue * rates[priceCurrency];\r\n  const markedUp = inAED * (1 + markupPercentage / 100);\r\n  const vatted   = markedUp * 1.05;\r\n  const ceiled   = Math.ceil(vatted / 5) * 5;\r\n  const modded   = removeMOD(ceiled);\r\n  return modded / 1.05;\r\n}\r\n\r\nexport function suggestKSAPrice(msrp_aed) {\r\n  if (msrp_aed == null) return null;\r\n  const raw    = msrp_aed * 1.03 * 1.15;\r\n  const ceiled = Math.ceil(raw / 5) * 5;\r\n  const modded = String(ceiled).slice(-2) === '00' ? ceiled - 0.05 : ceiled;\r\n  return modded / 1.15;\r\n}\r\n\r\nexport function suggestQATPrice(msrp_aed) {\r\n  if (msrp_aed == null) return null;\r\n  const raw    = msrp_aed * 1.01;\r\n  const ceiled = Math.ceil(raw / 5) * 5;\r\n  return String(ceiled).slice(-2) === '00' ? ceiled - 0.05 : ceiled;\r\n}\r\n\r\n// Apply additional markup to an already-prettified AED ex-VAT base, then re-prettify.\r\n// base (ex-VAT) → ×(1+add%) → ×1.05 VAT → ceil/5 → removeMOD → ÷1.05\r\nexport function applyAdditionalMarkupUAE(realMsrpAed, additionalPct) {\r\n  if (!realMsrpAed || !additionalPct) return realMsrpAed;\r\n  const vatted = realMsrpAed * (1 + additionalPct / 100) * 1.05;\r\n  const ceiled = Math.ceil(vatted / 5) * 5;\r\n  return removeMOD(ceiled) / 1.05;\r\n}\r\n\r\n// Compute all 6 MSRP fields from a source price — two prettification passes.\r\n// Pass 1: source → base markup → prettify → real_msrp_*\r\n// Pass 2: real_msrp_aed → additional markup → prettify → msrp_*\r\n// If additionalMarkupPct is null/0, msrp_* === real_msrp_*\r\nexport function calcMSRPs(priceValue, priceCurrency, baseMarkupPct, additionalMarkupPct, rates) {\r\n  const pf2 = v => v != null ? parseFloat(v.toFixed(2)) : null;\r\n  const rawReal = suggestUAEPrice(priceValue, priceCurrency, baseMarkupPct, rates);\r\n  if (rawReal == null) return null;\r\n  const real_msrp_aed = pf2(rawReal);\r\n  const real_msrp_sar = pf2(suggestKSAPrice(real_msrp_aed));\r\n  const real_msrp_qat = pf2(suggestQATPrice(real_msrp_aed));\r\n  const msrp_aed = additionalMarkupPct\r\n    ? pf2(applyAdditionalMarkupUAE(real_msrp_aed, additionalMarkupPct))\r\n    : real_msrp_aed;\r\n  const msrp_sar = pf2(suggestKSAPrice(msrp_aed));\r\n  const msrp_qat = pf2(suggestQATPrice(msrp_aed));\r\n  return { real_msrp_aed, real_msrp_sar, real_msrp_qat, msrp_aed, msrp_sar, msrp_qat };\r\n}\r\n\r\n// ── COST-BASED PRICING ────────────────────────────────────────\r\n\r\nexport const DEFAULT_COST_MARGIN_PCT = 25;\r\n\r\n/**\r\n * Compute all 6 MSRP fields from EXW cost by enforcing a target gross margin.\r\n * Pure EXW basis — no shipping, no customs (unlike calcProjectPrice).\r\n *\r\n * cost_aed     = exw_cost × FX rate\r\n * real_msrp    = cost_aed / (1 - margin%)  → ×1.05 VAT → ceil/5 → removeMOD → ÷1.05\r\n * msrp_*       = real_msrp after optional additional-markup second pass (same as calcMSRPs)\r\n * KSA/QAT derived from the final AED via the standard formulas.\r\n */\r\nexport function calcCostBasedMSRPs(exwCost, costCurrency, targetMarginPct, rates, additionalMarkupPct = null) {\r\n  if (exwCost == null || !costCurrency || !rates?.[costCurrency]) return null;\r\n  const margin = (targetMarginPct ?? DEFAULT_COST_MARGIN_PCT) / 100;\r\n  if (!(margin > 0 && margin < 1)) return null;\r\n  const pf2           = v => v != null ? parseFloat(v.toFixed(2)) : null;\r\n  const costAED       = exwCost * rates[costCurrency];\r\n  const raw           = costAED / (1 - margin);\r\n  const vatted        = raw * 1.05;\r\n  const ceiled        = Math.ceil(vatted / 5) * 5;\r\n  const real_msrp_aed = pf2(removeMOD(ceiled) / 1.05);\r\n  const real_msrp_sar = pf2(suggestKSAPrice(real_msrp_aed));\r\n  const real_msrp_qat = pf2(suggestQATPrice(real_msrp_aed));\r\n  const msrp_aed = additionalMarkupPct\r\n    ? pf2(applyAdditionalMarkupUAE(real_msrp_aed, additionalMarkupPct))\r\n    : real_msrp_aed;\r\n  const msrp_sar = pf2(suggestKSAPrice(msrp_aed));\r\n  const msrp_qat = pf2(suggestQATPrice(msrp_aed));\r\n  return { real_msrp_aed, real_msrp_sar, real_msrp_qat, msrp_aed, msrp_sar, msrp_qat };\r\n}\r\n\r\n// ── EMPLOYEE PRICE ────────────────────────────────────────────\r\n\r\nexport function calcEmployeePrice(item, rates) {\r\n  const landed = calcLandedCost(item, rates);\r\n  if (landed == null) return null;\r\n  return Math.floor(landed * 1.15 * 1.05);\r\n}\r\n\r\n// ── FORMAT HELPERS ────────────────────────────────────────────\r\n\r\nexport function formatMargin(margin) {\r\n  if (margin === null || margin === undefined) return { value: null, label: '—', status: 'null' };\r\n  const rounded = Math.round(margin * 10) / 10;\r\n  const status  = rounded >= 30 ? 'good' : rounded >= 20 ? 'warn' : 'bad';\r\n  return { value: rounded, label: `${rounded.toFixed(1)}%`, status };\r\n}\r\n\r\nexport const MARGIN_COLORS = {\r\n  good: '#3ecf8e',\r\n  warn: '#f5a623',\r\n  bad:  '#f26464',\r\n  null: '#444444',\r\n};\r\n\r\n// ── PROJECT ITEM PRICING ──────────────────────────────────────\r\nexport const DEFAULT_PROJECT_MARGIN_PCT = 25;\r\n\r\n/**\r\n * Cost-driven pricing for project items.\r\n * landed = cost × rate × (1 + ship%) × (1 + duty%)\r\n * Targets target_margin_pct (default 25%) on landed cost, adds 5% UAE VAT,\r\n * then prettifies. Unlike calcCostBasedMSRPs this prices off the LANDED cost,\r\n * so shipping and customs are included in the margin base.\r\n * Returns { msrp_aed_inc_vat, msrp_aed_ex_vat, landed_cost_aed } or null.\r\n */\r\nexport function calcProjectPrice({ cost, cost_currency, shipping_rate, customs_duty_rate, target_margin_pct }, rates) {\r\n  if (cost == null || cost === '' || !cost_currency || !rates?.[cost_currency]) return null;\r\n  const margin            = (target_margin_pct ?? DEFAULT_PROJECT_MARGIN_PCT) / 100;\r\n  if (!(margin > 0 && margin < 1)) return null;\r\n  const rate              = rates[cost_currency];\r\n  const ship              = (shipping_rate  ?? 0)   / 100;\r\n  const duty              = (customs_duty_rate ?? 5.5) / 100;\r\n  const costExCustomsSrc  = cost * (1 + ship);\r\n  const landedSrc         = costExCustomsSrc * (1 + duty);\r\n  const landedAED         = landedSrc * rate;\r\n  const raw               = landedAED / (1 - margin);   // gross margin target on landed cost\r\n  const vatted            = raw * 1.05;\r\n  const ceiled            = Math.ceil(vatted / 5) * 5;\r\n  const incVat            = removeMOD(ceiled);\r\n  const exVat             = parseFloat((incVat / 1.05).toFixed(2));\r\n  return {\r\n    msrp_aed_inc_vat:      parseFloat(incVat.toFixed(2)),\r\n    msrp_aed_ex_vat:       exVat,\r\n    msrp_sar:              suggestKSAPrice(exVat) != null ? parseFloat(suggestKSAPrice(exVat).toFixed(2)) : null,\r\n    msrp_qat:              suggestQATPrice(exVat) != null ? parseFloat(suggestQATPrice(exVat).toFixed(2)) : null,\r\n    landed_cost_aed:       parseFloat(landedAED.toFixed(2)),\r\n    target_margin_pct:     parseFloat((margin * 100).toFixed(2)),\r\n    cost_ex_customs_src:   parseFloat(costExCustomsSrc.toFixed(2)),\r\n    landed_cost_src:       parseFloat(landedSrc.toFixed(2)),\r\n  };\r\n}\r\n\r\n// ── VALIDATION ────────────────────────────────────────────────\r\n\r\nexport function validateItem(item) {\r\n  const errors = [];\r\n  if (!item.item_code?.trim())       errors.push('Item code is required');\r\n  if (!item.item_name?.trim())       errors.push('Item name is required');\r\n  if (!item.brand_code)              errors.push('Brand is required');\r\n  if (!item.cost_currency)           errors.push('Cost currency is required');\r\n  if (item.price_used !== 'cost_based' && !item.msrp_primary_currency) errors.push('Primary MSRP currency is required');\r\n  if (!item.price_used)              errors.push('Price used must be selected');\r\n  if (!item.price_source)            errors.push('Price source is required');\r\n  if (!item.cost_source)             errors.push('Cost source is required');\r\n  return errors;\r\n}\r\n","/******************************************************************************\nCopyright (c) Microsoft Corporation.\n\nPermission to use, copy, modify, and/or distribute this software for any\npurpose with or without fee is hereby granted.\n\nTHE SOFTWARE IS PROVIDED \"AS IS\" AND THE AUTHOR DISCLAIMS ALL WARRANTIES WITH\nREGARD TO THIS SOFTWARE INCLUDING ALL IMPLIED WARRANTIES OF MERCHANTABILITY\nAND FITNESS. IN NO EVENT SHALL THE AUTHOR BE LIABLE FOR ANY SPECIAL, DIRECT,\nINDIRECT, OR CONSEQUENTIAL DAMAGES OR ANY DAMAGES WHATSOEVER RESULTING FROM\nLOSS OF USE, DATA OR PROFITS, WHETHER IN AN ACTION OF CONTRACT, NEGLIGENCE OR\nOTHER TORTIOUS ACTION, ARISING OUT OF OR IN CONNECTION WITH THE USE OR\nPERFORMANCE OF THIS SOFTWARE.\n***************************************************************************** */\n/* global Reflect, Promise, SuppressedError, Symbol, Iterator */\n\nvar extendStatics = function(d, b) {\n  extendStatics = Object.setPrototypeOf ||\n      ({ __proto__: [] } instanceof Array && function (d, b) { d.__proto__ = b; }) ||\n      function (d, b) { for (var p in b) if (Object.prototype.hasOwnProperty.call(b, p)) d[p] = b[p]; };\n  return extendStatics(d, b);\n};\n\nexport function __extends(d, b) {\n  if (typeof b !== \"function\" && b !== null)\n      throw new TypeError(\"Class extends value \" + String(b) + \" is not a constructor or null\");\n  extendStatics(d, b);\n  function __() { this.constructor = d; }\n  d.prototype = b === null ? Object.create(b) : (__.prototype = b.prototype, new __());\n}\n\nexport var __assign = function() {\n  __assign 